package net.civeira.phylax.feature.oauth.authentication.application.token;

import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.feature.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.session.domain.gateway.SessionStoreGateway;
import net.civeira.phylax.feature.oauth.tokensecurity.application.JwtTokenBuilder;
import net.civeira.phylax.feature.oauth.tokensecurity.application.RefreshFamily;
import net.civeira.phylax.feature.oauth.tokensecurity.domain.AutorizationToken;

/**
 * Issues the access, refresh and ID tokens of a user grant and binds them to its session.
 *
 * <p>
 * The claims and signature come from {@link JwtTokenBuilder} (and its {@code ClaimsMapper}), the
 * single emission point per token type. This service only adds the session bookkeeping: the JTIs of
 * a code exchange are registered on the authorization session, and those of a rotation replace the
 * previous refresh JTI, so logout and session revocation reach every token of the grant.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class TokenIssuer {

  private final JwtTokenBuilder tokenBuilder;
  private final SessionStoreGateway sessionStore;

  public AutorizationToken issueClientCredentials(String tenant, ClientDetails client,
      List<String> scopes, List<String> audiences) {
    AutorizationToken token =
        tokenBuilder.buildClientCredentialsToken(tenant, client, scopes, audiences);
    AuthenticationData auth = new AuthenticationData();
    auth.setUsername(client.getClientId());
    auth.setUid(UUID
        .nameUUIDFromBytes((tenant + ":" + client.getClientId()).getBytes(StandardCharsets.UTF_8))
        .toString());
    auth.setTenant(tenant);
    auth.setScopes(scopes);
    auth.setAudiences(audiences);
    String sessionId = UUID.randomUUID().toString();
    sessionStore.saveSession(sessionId, client, "client_credentials", auth, sessionId);
    tokenBuilder.tokenJti(token.getAccessToken(), tenant).ifPresent(jti -> sessionStore
        .updateTokenJtis(sessionId, client.getClientId(), jti, UUID.randomUUID().toString()));
    return token;
  }

  /**
   * Issues the token of a token exchange, with its own revocable session record (task 3.8).
   */
  public AutorizationToken issueExchanged(String tenant, ClientDetails client,
      AuthenticationData auth, java.util.Map<String, Object> act) {
    AutorizationToken token = tokenBuilder.buildExchangedToken(tenant, client, auth, act);
    String sessionId = UUID.randomUUID().toString();
    sessionStore.saveSession(sessionId, client, JwtTokenBuilder.TOKEN_EXCHANGE, auth, sessionId);
    tokenBuilder.tokenJti(token.getAccessToken(), tenant).ifPresent(jti -> sessionStore
        .updateTokenJtis(sessionId, client.getClientId(), jti, UUID.randomUUID().toString()));
    return token;
  }

  /**
   * Issues the tokens of a grant.
   *
   * @param tenant tenant
   * @param client authenticated client
   * @param grantType grant type recorded in the token
   * @param auth authenticated user and granted scopes
   * @param request request context (scope, nonce, state, audiences)
   * @param sessionId authorization session of a code exchange
   * @param previousRefreshToken refresh token being rotated
   * @param family refresh family of the grant
   * @return the issued tokens
   */
  public AutorizationToken issue(String tenant, ClientDetails client, String grantType,
      AuthenticationData auth, AuthRequest request, Optional<String> sessionId,
      Optional<String> previousRefreshToken, RefreshFamily family) {
    AutorizationToken token =
        tokenBuilder.buildToken(tenant, client, grantType, auth, request, family);
    Optional<String> accessJti = tokenBuilder.tokenJti(token.getAccessToken(), tenant);
    // A client without the refresh_token grant gets no refresh token: its session keeps an unused
    // placeholder JTI, so logout still reaches the access token.
    Optional<String> refreshJti =
        token.getRefreshToken() == null ? Optional.of(UUID.randomUUID().toString())
            : tokenBuilder.tokenJti(token.getRefreshToken(), tenant);
    if (accessJti.isPresent() && refreshJti.isPresent()) {
      if (sessionId.isPresent() && !sessionId.get().isBlank()) {
        sessionStore.updateTokenJtis(sessionId.get(), client.getClientId(), accessJti.get(),
            refreshJti.get());
      } else if (previousRefreshToken.isPresent()) {
        tokenBuilder.tokenJti(previousRefreshToken.get(), tenant)
            .ifPresent(oldRefreshJti -> sessionStore.updateTokenJtisByRefreshJti(oldRefreshJti,
                accessJti.get(), refreshJti.get()));
      } else {
        String standaloneSession = UUID.randomUUID().toString();
        sessionStore.saveSession(standaloneSession, client, grantType, auth, standaloneSession);
        sessionStore.updateTokenJtis(standaloneSession, client.getClientId(), accessJti.get(),
            refreshJti.get());
      }
    }
    return token;
  }
}
